from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

import heapq
from itertools import combinations, product


def _routes(minimum_duration, exact_coupons):
    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source = data["source"]
        initial_mask = bit.get(source, 0)
        budget = data["coupons"]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start = (source, initial_mask, 0)
        best = {start: data["start"]}
        queue = [(data["start"], source, initial_mask, 0)]
        while queue:
            time, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if best.get(state) != time:
                continue
            if (node == data["target"] and mask == full and
                    (not exact_coupons or used == budget)):
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                choices = [(edge["duration"], used)]
                if used < budget:
                    duration = max(minimum_duration,
                                   edge["duration"] - edge.get("discount", 0))
                    choices.append((duration, used + 1))
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                for duration, next_used in choices:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = (next_node, next_mask, next_used)
                    if arrival < best.get(nxt, float("inf")):
                        best[nxt] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
        return {"arrival": None}
    return solve


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    selected = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in selected or key > selected[event_id][0]:
            selected[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator, denominator):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    for _, event in selected.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _resolver(data):
    packages = data["packages"]
    names = list(packages)
    versions = {name: {row["version"]: row for row in rows}
                for name, rows in packages.items()}
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    ordered_names = sorted(names, reverse=True)
    domains = []
    for name in names:
        allowed = [v for v in versions[name]
                   if v not in blocked.get(name, []) and
                   (name not in pins or v == pins[name])]
        domains.append([None] + sorted(allowed))

    best_vector = None
    best_installation = None
    for assignment in product(*domains):
        chosen = dict(zip(names, assignment))
        constraints = {name: [] for name in names}
        valid = True
        for name, bounds in data["roots"].items():
            constraints[name].append(tuple(bounds))
            version = chosen[name]
            if version is None or not bounds[0] <= version <= bounds[1]:
                valid = False
                break
        if not valid:
            continue

        graph = {name: [] for name in names}
        for name, version in chosen.items():
            if version is None:
                continue
            row = versions[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                graph[name].append(target)
                constraints[target].append((dep["min"], dep["max"]))

        for name, ranges in constraints.items():
            version = chosen[name]
            if ranges and (version is None or
                           not all(low <= version <= high for low, high in ranges)):
                valid = False
                break
        if not valid:
            continue

        reachable = set()
        stack = list(data["roots"])
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(graph[name])
        if any((chosen[name] is not None) != (name in reachable) for name in names):
            continue

        # Reject cycles in the selected dependency closure.
        active, finished = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            for target in graph[name]:
                if not visit(target):
                    return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in reachable):
            continue

        vector = tuple(chosen[name] if chosen[name] is not None else -1
                       for name in ordered_names)
        if best_vector is None or vector < best_vector:
            best_vector = vector
            best_installation = {name: chosen[name] for name in names
                                 if chosen[name] is not None}
    if best_installation is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_installation}


def _jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    if mandatory & blocked or len(mandatory) > k:
        return {"error": "impossible"}
    candidates = [job for job in jobs if job["id"] not in blocked]
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for subset in combinations(candidates, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"], job["id"]))
        if any(a["start"] < b["end"] and b["start"] < a["end"]
               for i, a in enumerate(ordered) for b in ordered[i + 1:]):
            continue
        value = sum(job["value"] for job in subset)
        selected_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and selected_ids < best_ids)):
            best_value, best_ids = value, selected_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


SOLVERS = {
    "component_01": _routes(2, False),
    "component_02": _routes(2, True),
    "component_03": _routes(1, False),
    "component_04": _routes(1, True),
    "component_05": _routes(2, False),
    "component_06": _ledger,
    "component_07": _resolver,
    "component_08": _jobs,
}
